// Get the output from Execute Command node
const output = $input.first().json.stdout;

// Parse the output to extract just the Response
const lines = output.split('\n');
let response = '';
let sources = [];

// Look for the "Response:" line
let foundResponse = false;
for (let i = 0; i < lines.length; i++) {
  const line = lines[i];

  if (line.startsWith('Response:')) {
    // Get everything after "Response:"
    response = line.replace('Response:', '').trim();
    foundResponse = true;

    // Check next line for Sources
    if (i + 1 < lines.length && lines[i + 1].startsWith('Sources:')) {
      const sourcesStr = lines[i + 1].replace('Sources:', '').trim();
      try {
        sources = JSON.parse(sourcesStr);
      } catch (e) {
        sources = [sourcesStr];
      }
    }
    break;
  }
}

// If no Response: found, try to get the last meaningful line
if (!response) {
  // Look for lines that don't start with "Answer the question" or context markers
  for (let i = lines.length - 1; i >= 0; i--) {
    const line = lines[i].trim();
    if (line && 
        !line.startsWith('Answer the question') && 
        !line.startsWith('---') &&
        !line.startsWith('*') &&
        !line.includes('context:')) {
      response = line;
      break;
    }
  }
}

// Clean up the response (remove any remaining prompt text)
response = response.replace(/^Based on the context provided, /, '');

return {
  json: {
    output: response || 'No response found'
  }
};
